  metric: string
  status: 'proposed' | 'applied' | 'verified' | 'dropped'
  applyPrompt: string
  evidence?: string[]
  createdAt?: string
  updatedAt?: string
}

export type DebriefLedger = { version: 1; items: DebriefLedgerItem[] }

